// Short-lived proof that a report actually completed. Signed at the server,
// never generated by untrusted browser input.
const encoder=new TextEncoder();
function base64url(bytes){
  let s=""; for(const b of bytes)s+=String.fromCharCode(b);
  return btoa(s).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"");
}
function fromBase64url(raw){
  const s=atob(raw.replace(/-/g,"+").replace(/_/g,"/").padEnd(Math.ceil(raw.length/4)*4,"="));
  return Uint8Array.from(s,ch=>ch.charCodeAt(0));
}
async function keyFor(secret) {
  if(!secret)throw Error("SUS signing secret unavailable");
  return crypto.subtle.importKey("raw",encoder.encode("eloscanner-sus-v1:"+secret),
    {name:"HMAC",hash:"SHA-256"},false,["sign","verify"]);
}
async function signValue(value,secret){
  const data=base64url(encoder.encode(JSON.stringify(value)));
  const signature=await crypto.subtle.sign("HMAC",await keyFor(secret),encoder.encode(data));
  return data+"."+base64url(new Uint8Array(signature));
}
async function verifyValue(token,secret){
  if(typeof token!=="string"||token.length>1500)return null;
  const parts=token.split(".");
  if(parts.length!==2)return null;
  try{
    const valid=await crypto.subtle.verify("HMAC",await keyFor(secret),
      fromBase64url(parts[1]),encoder.encode(parts[0]));
    return valid?JSON.parse(new TextDecoder().decode(fromBase64url(parts[0]))):null;
  }catch{return null;}
}
async function issueReviewProof(username,secret) {
  const normalized=String(username||"").trim().toLowerCase();
  if(!/^[a-z0-9_-]{3,25}$/.test(normalized))throw Error("Invalid player");
  return signValue({type:"sus-review",user:normalized,expires:Date.now()+3*3600*1000},secret);
}
async function validateReviewProof(token,username,secret){
  const payload=await verifyValue(token,secret);
  return !!payload&&payload.type==="sus-review"&&payload.user===username&&
    Number.isFinite(payload.expires)&&payload.expires>Date.now();
}
function cookieValue(request,name){
  const cookie=request.headers.get("Cookie")||"";
  for(const part of cookie.split(";")){
    const [k,...v]=part.trim().split("=");
    if(k===name)return v.join("=");
  }
  return null;
}
async function getVoter(request,secret){
  const payload=await verifyValue(cookieValue(request,"eloscanner_voter"),secret);
  if(payload?.type==="sus-voter"&&/^[0-9a-f-]{36}$/i.test(payload.id))return {id:payload.id,cookie:null};
  const id=crypto.randomUUID();
  const signed=await signValue({type:"sus-voter",id},secret);
  return {id,cookie:"eloscanner_voter="+signed+
    "; Path=/api/sus; HttpOnly; Secure; SameSite=Lax; Max-Age=31536000"};
}

/* A short-lived start permit. Browser results are intentionally not accepted
   as trusted server-side classifications; this ticket is only for CIP UI. */
async function issueLocalReviewTicket(username, secret) {
  const user=String(username||"").trim().toLowerCase();
  if(!/^[a-z0-9_-]{3,25}$/.test(user))throw Error("Invalid player");
  return signValue({type:"local-v87-start",user,issued:Date.now(),nonce:crypto.randomUUID()},secret);
}
async function validateLocalReviewTicket(token, username, secret) {
  const payload=await verifyValue(token,secret);
  const age=Date.now()-Number(payload?.issued);
  return !!payload&&payload.type==="local-v87-start"&&payload.user===username&&
    typeof payload.nonce==="string"&&/^[0-9a-f-]{36}$/.test(payload.nonce)&&
    Number.isFinite(age)&&age>=2000&&age<=20*60*1000;
}

export {issueReviewProof,validateReviewProof,getVoter,issueLocalReviewTicket,validateLocalReviewTicket};
